#!/bin/bash
# Mission Control — Autonomous Agent Council + Memory + Automation + Integrations
# Self-extracting installer
# Run: chmod +x install.sh && ./install.sh

set -e

echo "🚀 Mission Control — Full Installation"
echo "======================================"

# Check if we're in the right place
if [ ! -d "$HOME/missioncontrol" ]; then
    echo "❌ Error: ~/missioncontrol not found. Please run from your home directory."
    exit 1
fi

MC_DIR="$HOME/missioncontrol"
BACKUP_DIR="$MC_DIR/.backup-$(date +%Y%m%d-%H%M%S)"

echo "📦 Creating backup at $BACKUP_DIR..."
mkdir -p "$BACKUP_DIR"
cp -r "$MC_DIR/backend/src" "$BACKUP_DIR/" 2>/dev/null || true
cp -r "$MC_DIR/web/src" "$BACKUP_DIR/" 2>/dev/null || true

echo "📁 Creating directories..."
mkdir -p "$MC_DIR/backend/src/council"
mkdir -p "$MC_DIR/backend/src/memory"
mkdir -p "$MC_DIR/backend/src/automation"
mkdir -p "$MC_DIR/backend/src/integrations"
mkdir -p "$MC_DIR/web/src"

echo "📝 Extracting files..."

# Function to extract embedded files
extract_file() {
    local dest="$1"
    local content="$2"
    echo "$content" | base64 -d > "$dest"
    echo "  ✓ $dest"
}


